import {RUNES,valid,describe} from './combo-design.mjs';
const $=id=>document.getElementById(id),ids=Object.keys(RUNES);let seq=valid(location.hash.slice(1))?location.hash.slice(1):'qqw';let branch=seq.slice(0,2);const recipe=s=>[...s].map(k=>RUNES[k].name).join(' → ');
function button(s){const d=describe(s);return `<button data-seq="${s}" class="node ${seq===s?'selected':''} ${seq.startsWith(s)?'path':''}" aria-pressed="${seq===s}"><span>${recipe(s)}</span><b>${d.name}</b></button>`;}
function render(){const base=seq[0],d=describe(seq);if(branch[0]!==base)branch=base+base;if(seq.length>1)branch=seq.slice(0,2);document.documentElement.style.setProperty('--accent',d.color);$('bases').innerHTML=['재료','형태','행동'].map(group=>`<div class="group"><small>${group}</small>${ids.filter(k=>RUNES[k].group===group).map(k=>`<button data-seq="${k}" aria-pressed="${base===k}" style="--color:${RUNES[k].color}">${RUNES[k].icon} ${RUNES[k].name}</button>`).join('')}</div>`).join('');const pool=$('repeat').checked?[...new Set(seq)]:ids;$('treeTitle').textContent=RUNES[base].name+'에서 시작';$('root').innerHTML=button(base);$('pairs').innerHTML=pool.map(k=>button(base+k)).join('');$('triples').innerHTML=pool.map(k=>button(branch+k)).join('');$('detail').innerHTML=`<span class="eyebrow">설계안 · ${seq.length===1?'1륜':seq.length+'중 2륜'}</span><h2>${d.name}</h2><p>${recipe(seq)}</p><div class="scene ${d.motion}"><span class="caster">♟</span><div class="effect ${d.shape}"></div><span class="target">♟</span></div><small>형태와 이동을 설명하는 개념 애니메이션입니다.</small><ol>${d.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="notice">${d.balance}</p><button id="reverse">순서 뒤집어 비교</button><button id="share">조합 링크 복사</button><p id="status" role="status"></p><p class="muted">같은 재료를 연속해서 넣으면 해당 성질을 강화합니다. 세 원도 2륜 조합입니다.</p>`;$('reverse').onclick=()=>select([...seq].reverse().join(''));$('share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);$('status').textContent='링크를 복사했습니다.'}catch{$('status').textContent='주소창의 링크를 복사해 주세요.'}};}
function select(s){if(!valid(s))return;seq=s;history.replaceState(null,'','#'+seq);render();}document.addEventListener('click',e=>{const b=e.target.closest('[data-seq]');if(b)select(b.dataset.seq)});$('repeat').onchange=render;window.addEventListener('hashchange',()=>{if(valid(location.hash.slice(1))){seq=location.hash.slice(1);render()}});render();
